function requireAdmin(action='hacer cambios'){
  if(!cloudReady||!cloudOnline){toast('Solo nube',`No se puede ${action} sin conexión activa con Supabase.`,'warn');return false}
  if(adminMode)return true;
  toast('Modo normal activo',`Activa Administrador para ${action}.`,'warn');
  return false;
}
function isMutationControl(el){
  const code=[el.getAttribute?.('onclick')||'',el.getAttribute?.('onchange')||''].join(' ');
  return /open(?:Account|Card|Category|Movement|Recurring|Receivable(?:Payment)?|Goal(?:Contribution)?)\b|delete(?:Goal|Receivable|Movement|Category)\b|reconcile(?:Account|Card)\b|toggle(?:Entity|Recurring)\b|postRecurringNow\b|addReceivableSplitRow\b/.test(code);
}
function adminControlledElements(){
  const set=new Set(document.querySelectorAll('[data-admin-action],[data-admin-field]'));
  document.querySelectorAll('button[onclick],input[type="checkbox"][onchange]').forEach(el=>{if(isMutationControl(el))set.add(el)});
  return [...set];
}
function updateAdminModeButton(){
  const b=$('adminModeBtn');if(!b)return;
  b.classList.toggle('adminActive',adminMode);
  b.setAttribute('aria-pressed',String(adminMode));
  b.title=adminMode?'Modo Administrador · volver a Normal':'Modo normal · activar Administrador';
  b.setAttribute('aria-label',b.title);
  b.innerHTML=adminMode?'<i class="fa-solid fa-shield-halved"></i><span>Administrador</span>':'<i class="fa-solid fa-shield-halved"></i><span>Normal</span>';
}
function closeEditingDialogs(){
  ['accountDialog','cardDialog','categoryDialog','movementDialog','recurringDialog','goalDialog','goalContributionDialog','receivableDialog','receivablePaymentDialog'].forEach(id=>{const d=$(id);if(d?.open)d.close()});
}
function applyAdminMode(){
  document.documentElement.dataset.editMode=adminMode?'admin':'normal';
  const canEdit=adminMode&&cloudReady&&cloudOnline;
  for(const el of adminControlledElements()){
    if(el.dataset.adminBaseDisabled===undefined)el.dataset.adminBaseDisabled=el.disabled?'1':'0';
    const baseDisabled=el.dataset.adminBaseDisabled==='1';
    el.disabled=!canEdit||baseDisabled;
    el.classList.toggle('adminLockedControl',!canEdit);
    if(!canEdit&&el.tagName==='BUTTON'&&!el.title)el.title=cloudOnline?'Disponible en modo Administrador':'Requiere conexión con Supabase';
  }
  updateAdminModeButton();
}
function toggleAdminMode(){
  if(adminMode){
    adminMode=false;
    closeEditingDialogs();
    applyAdminMode();
    toast('Modo normal','Edición protegida. Puedes consultar y navegar sin cambios accidentales.');
    return;
  }
  adminMode=true;
  applyAdminMode();
  toast('Modo Administrador activo','Los controles de edición están habilitados.','warn');
}

function categoryKey(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase()}
function categoryBlueprints(){return [
  {name:'Trabajo',group:'income',color:'#2f6fed',subs:['Sueldo','Bono','Gratificación','Utilidades','Otros']},
  {name:'Ingresos adicionales',group:'income',color:'#4e8cff',subs:['Freelance','Venta','Otros']},
  {name:'Rendimientos',group:'income',color:'#3d8f77',subs:['Intereses','Dividendos','Otros']},
  {name:'Alimentación',group:'expense',color:'#d87a55',subs:['Supermercado','Almuerzos','Restaurantes','Delivery','Snacks','Otros']},
  {name:'Vivienda y servicios',group:'expense',color:'#8f7863',subs:['Luz','Agua','Internet','Móvil','Mantenimiento','Hogar','Otros']},
  {name:'Transporte',group:'expense',color:'#567f9b',subs:['Metropolitano','Taxi / App','Combustible','Estacionamiento','Mantenimiento','Otros']},
  {name:'Salud y bienestar',group:'expense',color:'#3b947b',subs:['Consultas','Medicinas','Seguro','Gimnasio','Deporte','Otros']},
  {name:'Cuidado personal',group:'expense',color:'#bc6f9a',subs:['Barbería','Skincare','Higiene','Otros']},
  {name:'Educación y desarrollo',group:'expense',color:'#4d76b8',subs:['Inglés','Cursos','Libros','Suscripciones','Otros']},
  {name:'Entretenimiento y ocio',group:'expense',color:'#8d68bd',subs:['Cine','Streaming','Videojuegos','Salidas','Otros']},
  {name:'Compras personales',group:'expense',color:'#b67373',subs:['Ropa','Calzado','Tecnología','Accesorios','Otros']},
  {name:'Familia y compromisos',group:'expense',color:'#a36f83',subs:['Apoyo familiar','Regalos','Celebraciones','Otros']},
  {name:'Otros gastos',group:'expense',color:'#7f8994',subs:['Proyectos heredados','Otros']},
  {name:'Ahorro',group:'investment',color:'#2d7564',subs:['Fondo de emergencia','Metas','Otros']},
  {name:'Inversión financiera',group:'investment',color:'#397a6e',subs:['Fondos','Acciones / ETF','Renta fija','Otros']},
  {name:'Otros activos',group:'investment',color:'#607d73',subs:['Inversiones alternativas','Otros']}
]}
function buildCategoryModel(){return categoryBlueprints().map(c=>({id:uid(),name:c.name,group:c.group,budget:0,color:c.color,subcategories:c.subs.map(name=>({id:uid(),name,archived:false}))}))}
function findSubcategoryByName(c,name){const key=categoryKey(name);return (c?.subcategories||[]).find(s=>categoryKey(s.name)===key)}
function migrateCategoryModel(d){
  const oldCats=Array.isArray(d.categories)?d.categories:[],next=buildCategoryModel(),byName=new Map(next.map(c=>[categoryKey(c.name),c])),refMap=new Map();
  const legacy={
    'work':['Trabajo','Sueldo'],'otros ingresos':['Ingresos adicionales','Otros'],'comida':['Alimentación','Otros'],'snacks':['Alimentación','Snacks'],
    'deporte':['Salud y bienestar','Deporte'],'diversion':['Entretenimiento y ocio','Salidas'],'entretenimiento':['Entretenimiento y ocio','Otros'],
    'educacion':['Educación y desarrollo','Otros'],'hogar':['Vivienda y servicios','Hogar'],'otros gastos':['Otros gastos','Otros'],
    'proyectos':['Otros gastos','Proyectos heredados'],'ropa':['Compras personales','Ropa'],'salud':['Salud y bienestar','Otros'],
    'cuidado personal':['Cuidado personal','Otros'],'transporte':['Transporte','Otros'],'inversiones':['Inversión financiera','Otros']
  };
  for(const old of oldCats){
    const key=categoryKey(old.name),rule=legacy[key];let target=null,subId='';
    if(rule){target=byName.get(categoryKey(rule[0]));subId=findSubcategoryByName(target,rule[1])?.id||''}
    else if(byName.has(key)){target=byName.get(key)}
    else{target={id:uid(),name:old.name||'Categoría',group:old.group||'expense',budget:0,color:old.color||'#2f6fed',subcategories:Array.isArray(old.subcategories)?old.subcategories.map(x=>({id:x.id||uid(),name:x.name||'Subcategoría',archived:!!x.archived})):[]};next.push(target);byName.set(key,target)}
    target.budget=(+target.budget||0)+(+old.budget||0);refMap.set(old.id,{categoryId:target.id,subcategoryId:subId,legacyProject:key==='proyectos'});
  }
  const remap=x=>{if(!x||!x.categoryId)return;const m=refMap.get(x.categoryId);if(!m)return;x.categoryId=m.categoryId;if(!x.subcategoryId&&m.subcategoryId)x.subcategoryId=m.subcategoryId;if(m.legacyProject&&!x.tag)x.tag='Proyecto heredado'};
  (d.movements||[]).forEach(remap);(d.recurring||[]).forEach(remap);(d.receivables||[]).forEach(remap);
  d.categories=next;d.settings=d.settings||{};d.settings.categoryModelVersion=2;
}
function starter(){
  return {version:6,settings:{income:3700,fx:3.5,theme:'light',lookback:6,categoryModelVersion:2,hideFigures:false},accounts:[],cards:[],categories:buildCategoryModel(),movements:[],recurring:[],goals:[],receivables:[]};
}
function normalize(d){
  if(!d||typeof d!=='object')d=starter();
  d.version=6;d.settings=d.settings||{income:3700,fx:3.5,theme:'light',lookback:6,hideFigures:false};if(typeof d.settings.hideFigures!=='boolean')d.settings.hideFigures=false;
  d.accounts=Array.isArray(d.accounts)?d.accounts:[];d.cards=Array.isArray(d.cards)?d.cards:[];d.categories=Array.isArray(d.categories)?d.categories:[];
  d.movements=Array.isArray(d.movements)?d.movements:[];d.recurring=Array.isArray(d.recurring)?d.recurring:[];d.goals=Array.isArray(d.goals)?d.goals:[];d.receivables=Array.isArray(d.receivables)?d.receivables:[];
  if((+d.settings.categoryModelVersion||0)<2)migrateCategoryModel(d);
  d.categories.forEach(c=>{if(!c.group)c.group='expense';if(c.budget==null)c.budget=0;if(!c.color)c.color='#2f6fed';if(!Array.isArray(c.subcategories))c.subcategories=[];c.subcategories=c.subcategories.filter(x=>x&&x.name).map(x=>({id:x.id||uid(),name:categoryKey(x.name)==='suscripciones profesionales'?'Suscripciones':x.name,archived:!!x.archived}))});
  d.movements.forEach(x=>{if(x.subcategoryId==null)x.subcategoryId='';if(x.tag==null)x.tag=''});d.recurring.forEach(x=>{if(x.subcategoryId==null)x.subcategoryId='';if(x.tag==null)x.tag=''});d.receivables.forEach(x=>{if(x.subcategoryId==null)x.subcategoryId='';if(x.tag==null)x.tag=''});
  const oldStatements=Array.isArray(d.cardStatements)?d.cardStatements:[];
  d.cards.forEach(c=>{c.active=c.active!==false;if(!c.openingDate)c.openingDate=today();if(!c.cycle){const sts=oldStatements.filter(x=>x.cardId===c.id).sort((a,b)=>(a.statementDate||'').localeCompare(b.statementDate||'')),st=sts[sts.length-1];c.cycle={amount:st?+st.amount||0:0,startDate:st?.statementDate||today(),dueDate:st?.dueDate||''}}if(!Array.isArray(c.cycleHistory))c.cycleHistory=[];c.cycleHistory=c.cycleHistory.filter(x=>x&&x.startDate).sort((a,b)=>(a.startDate||'').localeCompare(b.startDate||''))});
  d.goals.forEach(g=>{g.active=g.active!==false;g.initial=+g.initial||0;g.target=+g.target||0;if(!Array.isArray(g.contributions))g.contributions=[];g.contributions=g.contributions.filter(x=>x&&x.date).map(x=>({...x,amount:+x.amount||0,type:x.type==='subtract'?'subtract':'add'}));});
  d.receivables.forEach(r=>{r.currency=r.currency||'PEN';r.treatment=r.treatment||'reimbursement';if(!Array.isArray(r.installments))r.installments=[];r.installments=r.installments.map(i=>({...i,amount:+i.amount||0,payments:Array.isArray(i.payments)?i.payments.map(p=>({...p,amount:+p.amount||0})):[]}));});
  return d;
}

