let modalPageScrollY=0,modalPageIsLocked=false;
function syncModalPageLock(){
  const hasOpen=!!document.querySelector('dialog[open]');
  if(hasOpen&&!modalPageIsLocked){
    modalPageScrollY=window.scrollY||document.documentElement.scrollTop||0;modalPageIsLocked=true;document.body.classList.add('modalPageLocked');document.body.style.top=`-${modalPageScrollY}px`;
  }else if(!hasOpen&&modalPageIsLocked){
    modalPageIsLocked=false;document.body.classList.remove('modalPageLocked');document.body.style.top='';window.scrollTo(0,modalPageScrollY);
  }
}
function initModalScrollIsolation(){
  const dialogs=[...document.querySelectorAll('dialog')];if(!dialogs.length)return;
  const observer=new MutationObserver(()=>requestAnimationFrame(syncModalPageLock));dialogs.forEach(d=>{observer.observe(d,{attributes:true,attributeFilter:['open']});d.addEventListener('close',()=>requestAnimationFrame(syncModalPageLock));d.addEventListener('cancel',()=>requestAnimationFrame(syncModalPageLock))});syncModalPageLock();
}
initModalScrollIsolation();


