function analyticsMovementProductKey(t){if(t.kind==='expense')return `${t.sourceType||'account'}:${t.sourceId||''}`;if(t.kind==='income'||t.kind==='reimbursement')return `account:${t.sourceId||''}`;if(t.kind==='refund')return `card:${t.cardId||''}`;if(t.kind==='card_payment')return `account:${t.sourceId||''}`;return ''}
