function analyticsFlowSummary(from,to){let income=0,expense=0,investment=0,count=0;for(const t of data.movements){if((t.date||'')<from||(t.date||'')>to||!['expense','income','reimbursement'].includes(t.kind)||!analyticsMovementIncluded(t))continue;const v=toPen(t.amount,movementCurrency(t)),group=cat(t.categoryId)?.group||(t.kind==='income'?'income':'expense');if(t.kind==='income'||group==='income')income+=v;else if(group==='investment')investment+=(t.kind==='reimbursement'?-v:v);else expense+=(t.kind==='reimbursement'?-v:v);count++}return {income,expense,investment,net:income-expense-investment,count}}
function analyticsCashAt(date){return data.accounts.filter(a=>analyticsProductSelected('account',a.id)).reduce((sum,a)=>sum+toPen(accountBalanceAt(a.id,date),a.currency),0)}
function analyticsDebtAt(date){return data.cards.filter(c=>analyticsProductSelected('card',c.id)).reduce((sum,c)=>sum+toPen(cardDebtAt(c.id,date),c.currency),0)}
