function analyticsBuckets(from,to,granularity){const out=[];if(!from||!to||from>to)return out;const finish=parseDate(to),cursor=parseDate(from);let guard=0;const labelRange=(a,b)=>{const da=parseDate(a),db=parseDate(b),ma=monthNames[da.getMonth()].slice(0,3),mb=monthNames[db.getMonth()].slice(0,3),ad=String(da.getDate()).padStart(2,'0'),bd=String(db.getDate()).padStart(2,'0');if(a===b)return `${ad}/${String(da.getMonth()+1).padStart(2,'0')}`;if(da.getMonth()===db.getMonth()&&da.getFullYear()===db.getFullYear())return `${ad}–${bd} ${ma}`;return `${ad} ${ma}–${bd} ${mb}`};while(cursor<=finish&&guard++<1200){let start=fmt(cursor),end=start,label='';if(granularity==='day'){label=`${String(cursor.getDate()).padStart(2,'0')}/${String(cursor.getMonth()+1).padStart(2,'0')}`;cursor.setDate(cursor.getDate()+1)}else if(granularity==='week'){const e=new Date(cursor),daysToSunday=(7-e.getDay())%7;e.setDate(e.getDate()+daysToSunday);if(e>finish)e.setTime(finish.getTime());end=fmt(e);label=labelRange(start,end);cursor.setTime(e.getTime());cursor.setDate(cursor.getDate()+1)}else{const e=new Date(cursor.getFullYear(),cursor.getMonth()+1,0);if(e>finish)e.setTime(finish.getTime());end=fmt(e);label=`${monthNames[cursor.getMonth()].slice(0,3)} ${String(cursor.getFullYear()).slice(2)}`;cursor.setTime(e.getTime());cursor.setDate(cursor.getDate()+1)}out.push({start,end,label})}return out}
