function openPnlDetail(scope,id,year,mi=null){
  clearDetailBreakdownState();
  const cutoff=selectedCutoff(),monthNames=['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'],series=pnlMonthlySeries(scope,id,year,cutoff),annual=series.reduce((sum,p)=>sum+p.value,0),selected=mi==null?annual:series[mi].value,rows=pnlDetailMovements(scope,id,year,mi,cutoff);let title='',group='';
  if(scope==='category'){const c=cat(id);if(!c)return;title=c.name;group=c.group==='income'?'Ingresos':c.group==='investment'?'Ahorro / Inversión':'Egresos'}else if(scope==='group'){group=id==='income'?'Ingresos':id==='investment'?'Ahorro / Inversión':'Egresos';title=`Total ${group}`}else{title='Ahorro / Flujo libre';group='Resultado'}
  $('detailEyebrow').textContent='P&L / Flujo';$('detailTitle').textContent=title;$('detailSubtitle').textContent=`${group} · ${mi==null?`Año ${year}`:`${monthNames[mi]} ${year}`} · corte ${prettyDate(cutoff)}`;$('detailChartTitle').textContent='Tendencia mensual';
  const cutoffMonth=cutoff.startsWith(`${year}-`)?Number(cutoff.slice(5,7)):12,monthsElapsed=Math.max(1,Math.min(12,cutoffMonth)),avg=annual/monthsElapsed,peak=series.slice(0,monthsElapsed).reduce((a,b)=>Math.abs(b.value)>Math.abs(a.value)?b:a,series[0]||{label:'—',value:0});$('detailStats').innerHTML=statCard(mi==null?'Total al Corte':'Periodo',pen(selected))+statCard('Acumulado del año',pen(annual))+statCard('Promedio mensual',pen(avg),`${monthsElapsed} ${monthsElapsed===1?'mes':'meses'} al Corte`)+statCard('Mes de mayor movimiento',peak.label,pen(peak.value));setDetailTrend(series.slice(0,monthsElapsed),'PEN',`Enero – ${prettyDate(cutoff)}`,'bar');if(scope==='category'){const periodCaption=mi==null?`Año ${year} · participación por subcategoría`:`${monthNames[mi]} ${year} · participación por subcategoría`;renderPnlBreakdown(id,year,mi,cutoff,periodCaption)}else{clearDetailBreakdownState();$('detailBreakdownBlock')?.classList.add('hidden')}renderDetailMovementRows(rows,'pnl');$('detailDialog').showModal();
}

function renderIndicators(cash,debt,due,inc,exp,inv,saving){
  const sr=inc?saving/inc*100:0,er=inc?exp/inc*100:0,dc=cash?debt/cash*100:0,line=data.cards.filter(c=>c.active).reduce((s,c)=>s+toPen(c.limit,c.currency),0),util=line?debt/line*100:0;
  $('indicators').innerHTML=`<div class="indicator"><span>Posición líquida</span><strong class="${cash-debt<0?'bad':'good'}">${pen(cash-debt)}</strong></div><div class="indicator"><span>Tasa de ahorro</span><strong class="${sr>=20?'good':sr<0?'bad':'warn'}">${pct(sr)}</strong></div><div class="indicator"><span>Egresos / ingresos</span><strong>${pct(er)}</strong></div><div class="indicator"><span>Pago TC / efectivo</span><strong>${pct(cash?due/cash*100:0)}</strong></div><div class="indicator"><span>Deuda TC / efectivo</span><strong class="${dc>100?'bad':dc>50?'warn':'good'}">${pct(dc)}</strong></div><div class="indicator"><span>Utilización líneas TC</span><strong class="${util>80?'bad':util>50?'warn':'good'}">${pct(util)}</strong></div><div class="indicator"><span>Ahorro / Inversión</span><strong>${pen(inv)}</strong></div>`;
}
function scheduledDueFrom(r,refDate){if(!r.startDate)return null;let d=parseDate(r.startDate),n=parseDate(refDate),g=0;while(d<n&&g++<2000)d=addPeriod(d,r.period);return d}
function renderUpcoming(){const cutoff=selectedCutoff(),rows=data.recurring.filter(r=>r.active).map(r=>({...r,n:cutoff===today()?nextDue(r):scheduledDueFrom(r,cutoff)})).filter(r=>r.n).sort((a,b)=>a.n-b.n).slice(0,6);$('upcoming').innerHTML=rows.length?rows.map(r=>`<div class="commitment"><div><div class="commitmentName">${esc(r.name)}</div><div class="commitmentMeta">${fmt(r.n)} · ${esc(srcName(r.sourceType,r.sourceId))}</div></div><div class="commitmentAmount">${money(r.amount,r.sourceType==='card'?(card(r.sourceId)?.currency||'PEN'):(account(r.sourceId)?.currency||'PEN'))}</div></div>`).join(''):'<div class="empty">Sin compromisos activos.</div>'}

function kindName(k){return {expense:'Gasto / inversión',income:'Ingreso',reimbursement:'Reembolso',transfer:'Transferencia',card_payment:'Pago TC',refund:'Devolución',adjustment:'Ajuste'}[k]||k}
function party(t){if(t.kind==='expense')return srcName(t.sourceType,t.sourceId);if(t.kind==='income'||t.kind==='reimbursement')return '→ '+srcName('account',t.sourceId);if(t.kind==='transfer')return `${srcName('account',t.sourceId)} → ${srcName('account',t.destinationId)}`;if(t.kind==='card_payment')return `${srcName('account',t.sourceId)} → ${srcName('card',t.cardId)}`;if(t.kind==='refund')return '→ '+srcName('card',t.cardId);return 'Conciliación'}
function renderMovements(){const m=$('mvMonth').value||monthNow(),cutoff=selectedCutoff(),k=$('mvKindFilter').value,c=$('mvCatFilter').value,q=$('mvSearch').value.toLowerCase(),rows=data.movements.filter(t=>{const hay=[t.description,t.note,t.tag,catName(t.categoryId),subcatName(t.categoryId,t.subcategoryId)].join(' ').toLowerCase();return(!m||t.date.startsWith(m))&&(t.date||'')<=cutoff&&(!k||t.kind===k)&&(!c||t.categoryId===c)&&(!q||hay.includes(q))}).sort((a,b)=>b.date.localeCompare(a.date));$('ledgerList').innerHTML=rows.length?rows.map(t=>{const path=t.categoryId?categoryPathText(t.categoryId,t.subcategoryId):'Sin categoría',tag=t.tag?`<div class="tagPill"><i class="fa-solid fa-tag"></i>${esc(t.tag)}</div>`:'';return `<div class="ledgerRow"><div class="ledgerDate">${t.date}</div><div class="ledgerType"><span class="typePill ${t.kind==='income'||t.kind==='refund'||t.kind==='reimbursement'?'good':t.kind==='expense'?'bad':'warn'}">${kindName(t.kind)}</span></div><div class="ledgerDescription"><div class="ledgerDesc">${esc(t.description)}</div>${t.note?`<div class="ledgerMeta">${esc(t.note)}</div>`:''}${tag}</div><div class="ledgerParty ledgerMeta">${esc(party(t))}</div><div class="ledgerCategory ledgerMeta">${esc(path)}</div><div class="ledgerAmount">${money(t.amount,movementCurrency(t))}</div><div class="ledgerActions">${t.receivableId?`<button class="btn small" onclick="navigateTo('receivables')"><i class="fa-solid fa-hand-holding-dollar"></i> Pendiente</button>`:`<button class="btn small" onclick="openMovement('${t.id}')"><i class="fa-regular fa-pen-to-square"></i> Editar</button>`}<button class="btn small danger" onclick="deleteMovement('${t.id}')"><i class="fa-regular fa-trash-can"></i> Eliminar</button></div></div>`}).join(''):'<div class="empty">No hay movimientos para este filtro.</div>'}

function renderAccounts(){const cutoff=selectedCutoff(),isToday=cutoff===today();$('accountsGrid').innerHTML=data.accounts.length?data.accounts.map(a=>{const b=accountBalanceAt(a.id,cutoff);return `<div class="entityCard"><div class="entityHeader"><div><div class="entityTitle"><i class="fa-solid fa-building-columns iconBlue"></i> ${esc(a.name)}</div><div class="entitySub">${esc(a.institution||a.type)} · ${a.currency}</div></div><span class="badge ${a.active?'good':'warn'}">${a.active?'Activa':'Archivada'}</span></div><div class="entityValueLabel">Saldo al ${prettyDate(cutoff)}</div><div class="entityValue ${b<0?'bad':''}">${money(b,a.currency)}</div><div class="entityStats"><div class="statBox"><div class="statLabel">Saldo base</div><div class="statValue">${money(a.openingBalance,a.currency)}</div></div><div class="statBox"><div class="statLabel">Fecha base</div><div class="statValue">${a.openingDate}</div></div></div><div class="entityActions"><button class="btn small" onclick="openAccount('${a.id}')"><i class="fa-regular fa-pen-to-square"></i> Editar</button><button class="btn small" onclick="reconcileAccount('${a.id}')"><i class="fa-solid fa-scale-balanced"></i> Conciliar ${isToday?'':'hoy'}</button><button class="btn small" onclick="toggleEntity('accounts','${a.id}')">${a.active?'Archivar':'Activar'}</button></div></div>`}).join(''):'<div class="empty">Agrega tu primera cuenta.</div>'}

function creditUsageClass(usage){return usage<=30?'utilGreen':usage<=50?'utilYellow':'utilRed'}
function renderCards(){const cutoff=selectedCutoff(),isToday=cutoff===today();$('cardsGrid').innerHTML=data.cards.length?data.cards.map(c=>{const cy=cardCycleAt(c.id,cutoff),usage=c.limit?Math.min(100,cy.debt/c.limit*100):0,av=Math.max(0,c.limit-cy.debt);return `<div class="creditCard"><div class="creditHeader"><div><div class="creditName"><i class="fa-solid fa-credit-card iconBlue"></i> ${esc(c.name)}</div><div class="creditBank">${esc(c.bank||'Tarjeta')} · ${c.currency}</div></div><span class="badge">${figuresHidden?'••••':usage.toFixed(0)+'%'} uso</span></div><div class="creditDebtLabel">Deuda total al ${prettyDate(cutoff)}</div><div class="creditDebt">${money(cy.debt,c.currency)}</div><div class="creditProgress"><div class="${creditUsageClass(usage)}" style="width:${usage}%"></div></div><div class="tileMeta">Disponible ${money(av,c.currency)} de ${money(c.limit,c.currency)}</div><div class="creditCycle"><div class="cycleBox"><div class="cycleLabel">Pago ciclo</div><div class="cycleValue">${money(cy.amount,c.currency)}</div></div><div class="cycleBox"><div class="cycleLabel">Pagado al Corte</div><div class="cycleValue">${money(cy.paid,c.currency)}</div></div><div class="cycleBox"><div class="cycleLabel">Pendiente</div><div class="cycleValue ${cy.remaining>0?'warn':'good'}">${money(cy.remaining,c.currency)}</div></div></div><div class="creditFooter"><div class="dueText">Vence: <strong>${cy.dueDate||'—'}</strong></div><div class="actions"><button class="btn small" onclick="openCard('${c.id}')"><i class="fa-regular fa-pen-to-square"></i> Editar ciclo</button><button class="btn small" onclick="reconcileCard('${c.id}')"><i class="fa-solid fa-scale-balanced"></i> Conciliar ${isToday?'':'hoy'}</button><button class="btn small" onclick="openCardPayment(\'${c.id}\')"><i class="fa-solid fa-wallet"></i> Pagar</button></div></div></div>`}).join(''):'<div class="empty">Agrega tu primera tarjeta.</div>'}

function renderRecurring(){const f=$('recActive').value,q=$('recSearch').value.toLowerCase(),rows=data.recurring.filter(r=>(f===''||String(r.active)===f)&&(!q||[r.name,r.tag,catName(r.categoryId),subcatName(r.categoryId,r.subcategoryId)].join(' ').toLowerCase().includes(q)));$('recurringGrid').innerHTML=rows.length?rows.map(r=>`<div class="entityCard"><div class="entityHeader"><div><div class="entityTitle"><i class="fa-solid fa-rotate iconBlue"></i> ${esc(r.name)}</div><div class="entitySub">${r.period==='weekly'?'Semanal':r.period==='annual'?'Anual':'Mensual'} · ${esc(categoryPathText(r.categoryId,r.subcategoryId))}</div>${r.tag?`<div class="tagPill"><i class="fa-solid fa-tag"></i>${esc(r.tag)}</div>`:''}</div><span class="badge ${r.autoPost?'good':'warn'}">${r.autoPost?'Auto':'Manual'}</span></div><div class="entityValueLabel">${r.kind==='income'?'Ingreso':'Gasto / inversión'}</div><div class="entityValue">${money(r.amount,r.sourceType==='card'?(card(r.sourceId)?.currency||'PEN'):(account(r.sourceId)?.currency||'PEN'))}</div><div class="entityStats"><div class="statBox"><div class="statLabel">Fuente</div><div class="statValue">${esc(srcName(r.sourceType,r.sourceId))}</div></div><div class="statBox"><div class="statLabel">Próxima</div><div class="statValue">${nextDue(r)?fmt(nextDue(r)):'—'}</div></div></div><div class="entityActions"><button class="btn small primary" onclick="postRecurringNow('${r.id}')"><i class="fa-solid fa-circle-check"></i> Registrar</button><button class="btn small" onclick="openRecurring('${r.id}')"><i class="fa-regular fa-pen-to-square"></i> Editar</button><button class="btn small" onclick="toggleRecurring('${r.id}')">${r.active?'Pausar':'Activar'}</button></div></div>`).join(''):'<div class="empty">No hay recurrentes.</div>'}

function renderCategories(){const {year,month}=selectedPeriod(),cutoff=selectedCutoff(),order={income:0,expense:1,investment:2},rows=[...data.categories].sort((a,b)=>(order[a.group]??9)-(order[b.group]??9)||a.name.localeCompare(b.name,'es'));$('categoryGrid').innerHTML=rows.map(c=>{const v=pnlValue(c.id,year,month,cutoff),label=categoryGroupLabel(c.group),subs=(c.subcategories||[]).filter(x=>!x.archived),chips=subs.slice(0,6).map(x=>`<span class="subcategoryChip">${esc(x.name)}</span>`).join('')+(subs.length>6?`<span class="subcategoryChip">+${subs.length-6}</span>`:'');return `<div class="entityCard"><div class="entityHeader"><div><div class="entityTitle"><i class="dot" style="background:${c.color}"></i>${esc(c.name)}</div><div class="entitySub">${label}</div></div><span class="badge">${label}</span></div><div class="subcategoryChips">${chips||'<span class="subcategoryChip">Sin subcategorías</span>'}</div><div class="entityValueLabel">Movimiento del periodo</div><div class="entityValue">${pen(v)}</div><div class="entityStats"><div class="statBox"><div class="statLabel">Presupuesto</div><div class="statValue">${pen(c.budget||0)}</div></div><div class="statBox"><div class="statLabel">Subcategorías</div><div class="statValue">${subs.length}</div></div></div><div class="entityActions"><button class="btn small" onclick="openCategory('${c.id}')"><i class="fa-regular fa-pen-to-square"></i> Editar</button><button class="btn small danger" onclick="deleteCategory('${c.id}')"><i class="fa-regular fa-trash-can"></i> Eliminar</button></div></div>`}).join('')}

function renderSettings(){$('incomeInput').value=data.settings.income;$('fxInput').value=data.settings.fx;$('lookbackInput').value=data.settings.lookback}

function upsert(arr,item){const i=arr.findIndex(x=>x.id===item.id);if(i>=0)arr[i]=item;else arr.push(item)}
function openAccount(id=''){if(!requireAdmin(id?'editar esta cuenta':'agregar una cuenta'))return;const a=account(id)||{};$('accountTitle').textContent=id?'Editar cuenta':'Nueva cuenta';$('accountId').value=id;$('accountName').value=a.name||'';$('accountInstitution').value=a.institution||'';$('accountType').value=a.type||'Ahorros';$('accountCurrency').value=a.currency||'PEN';$('accountOpening').value=a.openingBalance??'';$('accountOpeningDate').value=a.openingDate||today();$('accountActive').value=String(a.active??true);$('accountDialog').showModal()}
function openCard(id=''){if(!requireAdmin(id?'editar esta tarjeta':'agregar una tarjeta'))return;const c=card(id)||{},cy=c.cycle||{};$('cardTitle').textContent=id?'Editar tarjeta / ciclo':'Nueva tarjeta';$('cardId').value=id;$('cardName').value=c.name||'';$('cardBank').value=c.bank||'';$('cardCurrency').value=c.currency||'PEN';$('cardLimit').value=c.limit??'';$('cardOpeningDebt').value=c.openingDebt??0;$('cardOpeningDate').value=c.openingDate||today();$('cardCycleAmount').value=cy.amount??0;$('cardCycleStart').value=cy.startDate||today();$('cardCycleDue').value=cy.dueDate||'';$('cardActive').value=String(c.active??true);$('cardDialog').showModal()}
function paymentAccountOptsByCurrency(currency,blank=true){const same=data.accounts.filter(a=>a.active&&a.currency===currency);const list=same.length?same:data.accounts.filter(a=>a.active);return (blank?'<option value="">Selecciona...</option>':'')+list.map(a=>`<option value="${a.id}">${esc(a.name)} · ${a.currency} · ${money(accountBalance(a.id),a.currency)}</option>`).join('')}
function setCardPaymentMode(mode,amount){const cycleBtn=$('cardPaymentCycleBtn'),customBtn=$('cardPaymentCustomBtn'),amountInput=$('cardPaymentAmount');if(!cycleBtn||!customBtn||!amountInput)return;cycleBtn.classList.toggle('active',mode==='cycle');customBtn.classList.toggle('active',mode==='custom');if(mode==='cycle'&&Number.isFinite(amount)&&amount>0){amountInput.value=amount.toFixed(2)}else if(mode==='custom'&&(!amountInput.value||Number(amountInput.value)===0)){amountInput.value=''}$('cardPaymentAmountLabel').textContent=mode==='cycle'?'Monto a pagar':'Ingresa otro monto';setTimeout(()=>amountInput.focus(),0)}
function openCardPayment(id){if(!requireAdmin('registrar este pago'))return;const c=card(id);if(!c)return;const cy=cardCycleAt(id,today());const quickAmount=(cy.remaining>0?cy.remaining:cy.debt);$('cardPaymentCardId').value=id;$('cardPaymentDate').value=today();$('cardPaymentAccount').innerHTML=paymentAccountOptsByCurrency(c.currency||'PEN');const firstOption=[...$('cardPaymentAccount').options].find(o=>o.value);$('cardPaymentAccount').value=firstOption?.value||'';const cycleBtn=$('cardPaymentCycleBtn');cycleBtn.disabled=!(quickAmount>0);cycleBtn.textContent=cy.remaining>0?`Pago del ciclo · ${money(cy.remaining,c.currency)}`:(cy.debt>0?`Deuda total · ${money(cy.debt,c.currency)}`:'Sin saldo pendiente');$('cardPaymentContext').innerHTML=`<strong>${esc(c.name)}</strong><br>Deuda total hoy: ${money(cy.debt,c.currency)} · Pago pendiente del ciclo: ${money(cy.remaining,c.currency)}${cy.dueDate?` · Vence ${prettyDate(cy.dueDate)}`:''}.`;$('cardPaymentNote').value='';$('cardPaymentAmount').value=quickAmount>0?quickAmount.toFixed(2):'';setCardPaymentMode(quickAmount>0?'cycle':'custom',quickAmount);$('cardPaymentDialog').showModal()}
function categoryGroupLabel(group){return group==='income'?'Ingresos':group==='investment'?'Ahorro / Inversión':'Egresos'}
function usedSubcategoryIds(categoryId){const used=new Set();for(const collection of [data.movements,data.recurring,data.receivables])for(const x of collection||[])if(x.categoryId===categoryId&&x.subcategoryId)used.add(x.subcategoryId);return used}
function openCategory(id=''){if(!requireAdmin(id?'editar esta categoría':'agregar una categoría'))return;const c=cat(id)||{};$('categoryTitle').textContent=id?'Editar categoría':'Nueva categoría';$('categoryId').value=id;$('categoryName').value=c.name||'';$('categoryGroup').value=c.group||'expense';$('categoryBudget').value=c.budget??0;$('categoryColor').value=c.color||'#2f6fed';$('categorySubcategories').value=(c.subcategories||[]).filter(x=>!x.archived).map(x=>x.name).join('\n');$('categoryDialog').showModal()}
function allowedCategoryGroups(kind){return kind==='income'?['income']:kind==='expense'||kind==='reimbursement'?['expense','investment']:[]}
function categoryOptionsByGroups(groups,blank='Sin categoría'){const set=new Set(groups);return `<option value="">${blank}</option>`+data.categories.filter(c=>set.has(c.group)).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}
function refreshMovementCategories(categoryId='',subcategoryId=''){const el=$('movementCategory');if(!el)return;const old=categoryId||el.value,k=$('movementKind').value,groups=allowedCategoryGroups(k);el.innerHTML=categoryOptionsByGroups(groups,'Selecciona categoría');el.value=[...el.options].some(o=>o.value===old)?old:'';fillSubcategorySelect('movementSubcategory',el.value,subcategoryId||$('movementSubcategory')?.value||'')}
function refreshMvSources(){const st=$('movementSourceType').value,old=$('movementSourceId').value;$('movementSourceId').innerHTML=st==='card'?cardOpts():accountOpts();if([...$('movementSourceId').options].some(o=>o.value===old))$('movementSourceId').value=old;$('movementDestinationId').innerHTML=accountOpts();$('movementCardId').innerHTML=cardOpts()}
function updateMvForm(){const k=$('movementKind').value;if(k==='income'||k==='reimbursement'||k==='transfer'||k==='card_payment')$('movementSourceType').value='account';$('sourceTypeWrap').classList.toggle('hidden',k!=='expense');$('sourceWrap').classList.toggle('hidden',k==='refund');$('destWrap').classList.toggle('hidden',k!=='transfer');$('cardDestWrap').classList.toggle('hidden',!(k==='card_payment'||k==='refund'));const hasCategory=k==='expense'||k==='income'||k==='reimbursement';$('categoryWrap').classList.toggle('hidden',!hasCategory);$('subcategoryWrap').classList.toggle('hidden',!hasCategory);$('movementTag').closest('.span2').classList.toggle('hidden',!hasCategory);$('appliedWrap').classList.toggle('hidden',!(k==='transfer'||k==='card_payment'));$('appliedLabel').textContent=k==='card_payment'?'Monto aplicado a tarjeta':'Monto recibido';$('sourceLabel').textContent=k==='income'||k==='reimbursement'?'Cuenta destino':k==='transfer'?'Cuenta origen':k==='card_payment'?'Cuenta desde la que pagas':'Cuenta / tarjeta';refreshMvSources();refreshMovementCategories();preview()}
function preview(){const k=$('movementKind').value,amt=+$('movementAmount').value||0,ap=+$('movementAppliedAmount').value||amt,s=$('movementSourceId').value,d=$('movementDestinationId').value,c=$('movementCardId').value,st=$('movementSourceType').value,id=$('movementId').value;let txt='Completa los datos para ver el impacto.';if(k==='expense'&&s)txt=st==='account'?`${srcName('account',s)} quedaría en ${money(accountBalance(s,id)-amt,account(s)?.currency||'PEN')}.`:`${srcName('card',s)} tendría deuda ${money(cardDebt(s,id)+amt,card(s)?.currency||'PEN')}.`;if((k==='income'||k==='reimbursement')&&s)txt=`${srcName('account',s)} quedaría en ${money(accountBalance(s,id)+amt,account(s)?.currency||'PEN')}.`;if(k==='transfer'&&s&&d)txt=`${srcName('account',s)} → ${money(accountBalance(s,id)-amt,account(s)?.currency||'PEN')} | ${srcName('account',d)} → ${money(accountBalance(d,id)+ap,account(d)?.currency||'PEN')}.`;if(k==='card_payment'&&s&&c){const cy=cardCycle(c,id);txt=`Caja → ${money(accountBalance(s,id)-amt,account(s)?.currency||'PEN')} | deuda TC → ${money(Math.max(0,cardDebt(c,id)-ap),card(c)?.currency||'PEN')} | pago pendiente → ${money(Math.max(0,cy.remaining-ap),card(c)?.currency||'PEN')}.`;}if(k==='refund'&&c)txt=`Deuda ${srcName('card',c)} → ${money(Math.max(0,cardDebt(c,id)-amt),card(c)?.currency||'PEN')}.`;$('impact').textContent=txt}
function openMovement(id=''){if(!requireAdmin(id?'editar este movimiento':'registrar un movimiento'))return;const t=data.movements.find(x=>x.id===id)||{};$('movementTitle').textContent=id?'Editar movimiento':'Nuevo movimiento';$('movementId').value=id;$('movementDate').value=t.date||today();$('movementKind').value=t.kind==='adjustment'?'expense':(t.kind||'expense');$('movementDescription').value=t.kind==='adjustment'?'':(t.description||'');$('movementSourceType').value=t.sourceType||'account';updateMvForm();$('movementSourceId').value=t.sourceId||'';$('movementDestinationId').value=t.destinationId||'';$('movementCardId').value=t.cardId||'';refreshMovementCategories(t.categoryId||'',t.subcategoryId||'');$('movementTag').value=t.tag||'';$('movementAmount').value=t.amount??'';$('movementAppliedAmount').value=t.appliedAmount??'';$('movementNote').value=t.note||'';preview();$('movementDialog').showModal()}
function refreshRecSources(){const st=$('recurringSourceType').value,old=$('recurringSourceId').value;$('recurringSourceId').innerHTML=st==='card'?cardOpts():accountOpts();if([...$('recurringSourceId').options].some(o=>o.value===old))$('recurringSourceId').value=old}
function refreshRecurringCategories(categoryId='',subcategoryId=''){const el=$('recurringCategory'),kind=$('recurringKind').value,old=categoryId||el.value;el.innerHTML=categoryOptionsByGroups(kind==='income'?['income']:['expense','investment'],'Selecciona categoría');el.value=[...el.options].some(o=>o.value===old)?old:'';fillSubcategorySelect('recurringSubcategory',el.value,subcategoryId||$('recurringSubcategory')?.value||'')}
function updateRecForm(){if($('recurringKind').value==='income')$('recurringSourceType').value='account';$('recurringSourceType').disabled=$('recurringKind').value==='income';refreshRecSources();refreshRecurringCategories()}
