function addMonthsIso(dateStr,months){const d=parseDate(dateStr),day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+months);const last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,last));return isoDateLocal(d)}
function categoryOptionsFor(groups,blankText='Sin categoría'){const set=new Set(groups);return `<option value="">${blankText}</option>`+data.categories.filter(c=>set.has(c.group)).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}
function accountOptsByCurrency(currency,blank=true){return (blank?'<option value="">Selecciona...</option>':'')+data.accounts.filter(a=>a.active&&a.currency===currency).map(a=>`<option value="${a.id}">${esc(a.name)} · ${a.currency} · ${money(accountBalance(a.id),a.currency)}</option>`).join('')}
