function addReceivableSplitRow(name='',amount=''){const host=$('receivableSplitRows');if(!host)return;const row=document.createElement('div');row.className='receivableSplitEditRow';row.innerHTML=`<input class="receivableSplitName" placeholder="Nombre" value="${esc(name||'')}"><input class="receivableSplitAmount" type="number" min="0.01" step=".01" placeholder="0.00" value="${amount!==''&&amount!=null?Number(amount):''}"><button type="button" class="btn small danger receivableSplitRemove" title="Eliminar" aria-label="Eliminar persona"><i class="fa-solid fa-xmark"></i></button>`;row.querySelectorAll('input').forEach(el=>el.addEventListener('input',recalcReceivableSplitTotal));row.querySelector('.receivableSplitRemove').onclick=()=>{row.remove();if(!host.children.length)addReceivableSplitRow();recalcReceivableSplitTotal()};host.appendChild(row);recalcReceivableSplitTotal()}
function setReceivableSplitRows(items=[]){const host=$('receivableSplitRows');if(!host)return;host.innerHTML='';(items.length?items:[{name:'',amount:''}]).forEach(x=>addReceivableSplitRow(x.name||x.label||'',x.amount??''));recalcReceivableSplitTotal()}
function buildPunctualInstallments(items,startDate){return items.map(x=>({id:uid(),label:x.name,dueDate:startDate,amount:+x.amount||0,payments:[]}))}

function installmentPaidAt(inst,cutoff=selectedCutoff()){return (inst.payments||[]).filter(p=>(p.date||'')<=cutoff).reduce((s,p)=>s+(+p.amount||0),0)}
function installmentRemainingAt(inst,cutoff=selectedCutoff()){return Math.max(0,(+inst.amount||0)-installmentPaidAt(inst,cutoff))}
function receivableOutstandingAt(r,cutoff=selectedCutoff()){return (r.installments||[]).reduce((s,i)=>s+installmentRemainingAt(i,cutoff),0)}
function receivableReceivedAt(r,cutoff=selectedCutoff()){return Math.max(0,(+r.total||0)-receivableOutstandingAt(r,cutoff))}
function receivableNextInstallment(r,cutoff=selectedCutoff()){return (r.installments||[]).map(i=>({i,remaining:installmentRemainingAt(i,cutoff)})).filter(x=>x.remaining>.005).sort((a,b)=>(a.i.dueDate||'').localeCompare(b.i.dueDate||''))[0]||null}
function receivableIsOverdue(r,cutoff=selectedCutoff()){return (r.installments||[]).some(i=>(i.dueDate||'')<cutoff&&installmentRemainingAt(i,cutoff)>.005)}
function receivableStatus(r,cutoff=selectedCutoff()){const out=receivableOutstandingAt(r,cutoff);if(out<=.005)return 'paid';return receivableIsOverdue(r,cutoff)?'overdue':'open'}
function goalProgressAt(g,cutoff=selectedCutoff()){return Math.max(0,(+g.initial||0)+(g.contributions||[]).filter(c=>(c.date||'')<=cutoff).reduce((s,c)=>s+(c.type==='subtract'?-1:1)*(+c.amount||0),0))}
function goalPctAt(g,cutoff=selectedCutoff()){return g.target?Math.max(0,Math.min(100,goalProgressAt(g,cutoff)/(+g.target||1)*100)):0}
function goalMonthsLeft(g,cutoff=selectedCutoff()){if(!g.dueDate||g.dueDate<=cutoff)return 0;const a=parseDate(cutoff),b=parseDate(g.dueDate);return Math.max(1,(b.getFullYear()-a.getFullYear())*12+b.getMonth()-a.getMonth()+(b.getDate()>a.getDate()?1:0))}
function priorityLabel(v){return v==='high'?'Alta':v==='low'?'Baja':'Media'}
function priorityClass(v){return v==='high'?'bad':v==='low'?'':'warn'}
function renderPlanningPreview(){const cutoff=selectedCutoff(),open=data.receivables.filter(r=>receivableOutstandingAt(r,cutoff)>.005),total=open.reduce((s,r)=>s+toPen(receivableOutstandingAt(r,cutoff),r.currency||'PEN'),0),overdue=open.filter(r=>receivableIsOverdue(r,cutoff)),next=open.map(r=>({r,n:receivableNextInstallment(r,cutoff)})).filter(x=>x.n).sort((a,b)=>(a.n.i.dueDate||'').localeCompare(b.n.i.dueDate||'')).slice(0,2);$('dashReceivableTotal').textContent=pen(total);$('dashReceivableMeta').textContent=open.length?`${open.length} ${open.length===1?'pendiente':'pendientes'} · ${overdue.length} vencido${overdue.length===1?'':'s'}`:'Sin pendientes registrados.';$('dashReceivableList').innerHTML=next.length?next.map(x=>`<div class="planningMiniRow"><span>${esc(x.r.name)}<small>${x.r.mode==='one_time'&&x.n.i.label?`${esc(x.n.i.label)} · `:''}${x.n.i.dueDate?prettyDate(x.n.i.dueDate):'Sin fecha'}</small></span><strong>${money(x.n.remaining,x.r.currency)}</strong></div>`).join(''):'<div class="planningEmpty">Nada próximo por cobrar.</div>';const active=data.goals.filter(g=>g.active!==false&&goalProgressAt(g,cutoff)<(+g.target||0)),target=active.reduce((s,g)=>s+toPen(g.target,g.currency||'PEN'),0),progress=active.reduce((s,g)=>s+toPen(goalProgressAt(g,cutoff),g.currency||'PEN'),0),top=[...active].sort((a,b)=>goalPctAt(b,cutoff)-goalPctAt(a,cutoff)).slice(0,2);$('dashGoalProgress').textContent=pen(progress);$('dashGoalMeta').textContent=active.length?`${pct(target?progress/target*100:0)} del objetivo conjunto · ${active.length} activ${active.length===1?'o':'os'}`:'Aún no tienes objetivos.';$('dashGoalList').innerHTML=top.length?top.map(g=>`<div class="planningGoalRow"><div><span>${esc(g.name)}</span><small>${pct(goalPctAt(g,cutoff))}</small></div><div class="miniProgress"><i style="width:${goalPctAt(g,cutoff)}%"></i></div></div>`).join(''):'<div class="planningEmpty">Crea una meta para empezar.</div>'}
function renderReceivables(){if(!$('receivableGrid'))return;const cutoff=selectedCutoff(),status=$('receivableStatusFilter')?.value||'open',q=($('receivableSearch')?.value||'').toLowerCase(),rows=data.receivables.filter(r=>{const st=receivableStatus(r,cutoff),statusOk=status==='all'||st===status||(status==='open'&&(st==='open'||st==='overdue')),splitNames=(r.installments||[]).map(i=>i.label||'').join(' '),searchText=`${r.name||''} ${r.person||''} ${splitNames} ${r.tag||''} ${categoryPathText(r.categoryId,r.subcategoryId)}`.toLowerCase();return statusOk&&(!q||searchText.includes(q))});const totalOpen=data.receivables.reduce((sum,r)=>sum+toPen(receivableOutstandingAt(r,cutoff),r.currency||'PEN'),0),overdue=data.receivables.filter(r=>receivableIsOverdue(r,cutoff)).reduce((sum,r)=>sum+toPen((r.installments||[]).filter(i=>(i.dueDate||'')<cutoff).reduce((a,i)=>a+installmentRemainingAt(i,cutoff),0),r.currency||'PEN'),0),next30Date=parseDate(cutoff);next30Date.setDate(next30Date.getDate()+30);const next30=isoDateLocal(next30Date),soon=data.receivables.reduce((sum,r)=>sum+toPen((r.installments||[]).filter(i=>(i.dueDate||'')>=cutoff&&(i.dueDate||'')<=next30).reduce((a,i)=>a+installmentRemainingAt(i,cutoff),0),r.currency||'PEN'),0),receivedMonth=data.receivables.reduce((sum,r)=>sum+toPen((r.installments||[]).flatMap(i=>i.payments||[]).filter(p=>(p.date||'').startsWith(cutoff.slice(0,7))&&(p.date||'')<=cutoff).reduce((a,p)=>a+(+p.amount||0),0),r.currency||'PEN'),0);$('receivableSummary').innerHTML=summaryCard('Por cobrar',pen(totalOpen),'fa-hand-holding-dollar')+summaryCard('Vencido',pen(overdue),'fa-triangle-exclamation',overdue>0?'bad':'')+summaryCard('Próx. 30 días',pen(soon),'fa-calendar-days')+summaryCard('Cobrado este mes',pen(receivedMonth),'fa-circle-check','good');$('receivableGrid').innerHTML=rows.length?rows.map(r=>{const out=receivableOutstandingAt(r,cutoff),received=receivableReceivedAt(r,cutoff),progress=r.total?Math.min(100,received/(+r.total||1)*100):0,next=receivableNextInstallment(r,cutoff),st=receivableStatus(r,cutoff),isPunctual=r.mode!=='installments',installments=(r.installments||[]).map((i,idx)=>{const rem=installmentRemainingAt(i,cutoff),paid=rem<=.005;if(isPunctual){const label=i.label||r.person||`Pendiente ${idx+1}`;return `<div class="installmentRow splitPaymentRow ${paid?'paid':''}"><div class="splitPaymentMain"><input class="splitPaymentCheck" type="checkbox" ${paid?'checked disabled':''} aria-label="${paid?'Cobrado':'Marcar como cobrado'}: ${esc(label)}" onchange="if(this.checked){this.checked=false;openReceivablePayment('${r.id}','${i.id}')}"><span class="splitPaymentName"><strong>${esc(label)}</strong><small>${paid?'Cobrado':`Esperado ${prettyDate(i.dueDate)}`}</small></span></div><strong class="splitPaymentAmount">${paid?'Cobrado':money(rem,r.currency)}</strong></div>`}return `<div class="installmentRow ${paid?'paid':''}"><span><i class="fa-solid ${paid?'fa-circle-check':'fa-clock'}"></i> Cuota ${idx+1} · ${prettyDate(i.dueDate)}</span><strong>${paid?'Cobrado':money(rem,r.currency)}</strong></div>`}).join(''),subtitle=isPunctual?`${(r.installments||[]).length} ${(r.installments||[]).length===1?'persona':'personas'} · Puntual`:`${esc(r.person||'Sin persona')} · ${r.installments.length} cuotas`;return `<div class="receivableCard ${st==='overdue'?'overdue':''}"><div class="receivableTop"><div><div class="entityTitle"><i class="fa-solid fa-hand-holding-dollar iconBlue"></i>${esc(r.name)}</div><div class="entitySub">${subtitle}</div><div class="entitySub">${esc(categoryPathText(r.categoryId,r.subcategoryId))}</div>${r.tag?`<div class="tagPill"><i class="fa-solid fa-tag"></i>${esc(r.tag)}</div>`:''}</div><span class="badge ${st==='paid'?'good':st==='overdue'?'bad':'warn'}">${st==='paid'?'Cobrado':st==='overdue'?'Vencido':'Pendiente'}</span></div><div class="receivableAmountRow"><div><span>Por cobrar</span><strong>${money(out,r.currency)}</strong></div><div><span>Recibido</span><strong>${money(received,r.currency)}</strong></div></div><div class="goalProgress"><i style="width:${progress}%"></i></div><div class="receivableNext">${next?`${isPunctual?`Siguiente: <strong>${esc(next.i.label||'Pendiente')}</strong>`:`Próximo: <strong>${prettyDate(next.i.dueDate)}</strong>`} · ${money(next.remaining,r.currency)}`:'Completamente cobrado'}</div><div class="installmentList">${installments}</div><div class="entityActions">${!isPunctual&&next?`<button class="btn small primary" onclick="openReceivablePayment('${r.id}','${next.i.id}')"><i class="fa-solid fa-circle-dollar-to-slot"></i> Cobrar</button>`:''}<button class="btn small" onclick="openReceivable('${r.id}')"><i class="fa-regular fa-pen-to-square"></i> Editar</button><button class="btn small danger" onclick="deleteReceivable('${r.id}')"><i class="fa-regular fa-trash-can"></i> Eliminar</button></div></div>`}).join(''):'<div class="empty">No hay pendientes para este filtro.</div>'}
function summaryCard(label,value,icon,cls=''){return `<div class="card miniSummary"><i class="fa-solid ${icon}"></i><div><span>${label}</span><strong class="${cls}">${value}</strong></div></div>`}
function renderGoals(){if(!$('goalGrid'))return;const cutoff=selectedCutoff(),status=$('goalStatusFilter')?.value||'active',q=($('goalSearch')?.value||'').toLowerCase(),rows=data.goals.filter(g=>{const done=goalProgressAt(g,cutoff)>=(+g.target||0)&&(+g.target||0)>0,statusOk=status==='all'||(status==='completed'&&done)||(status==='active'&&!done&&g.active!==false);return statusOk&&(!q||(g.name||'').toLowerCase().includes(q))});const active=data.goals.filter(g=>g.active!==false&&goalProgressAt(g,cutoff)<(+g.target||0)),target=active.reduce((s,g)=>s+toPen(g.target,g.currency||'PEN'),0),current=active.reduce((s,g)=>s+toPen(goalProgressAt(g,cutoff),g.currency||'PEN'),0),remaining=Math.max(0,target-current),dueSoon=active.filter(g=>g.dueDate&&g.dueDate>=cutoff&&g.dueDate<=addMonthsIso(cutoff,3)).length;$('goalSummary').innerHTML=summaryCard('Meta total',pen(target),'fa-bullseye')+summaryCard('Acumulado',pen(current),'fa-piggy-bank','good')+summaryCard('Restante',pen(remaining),'fa-arrow-trend-up')+summaryCard('Vencen en 3 meses',String(dueSoon),'fa-calendar-check');$('goalGrid').innerHTML=rows.length?rows.map(g=>{const cur=goalProgressAt(g,cutoff),target=+g.target||0,p=goalPctAt(g,cutoff),remaining=Math.max(0,target-cur),months=goalMonthsLeft(g,cutoff),monthly=months?remaining/months:remaining,done=target>0&&cur>=target;return `<div class="goalCard ${done?'complete':''}"><div class="goalTop"><div><div class="entityTitle"><i class="fa-solid fa-bullseye iconBlue"></i>${esc(g.name)}</div><div class="entitySub">${g.dueDate?`Fecha objetivo ${prettyDate(g.dueDate)}`:'Sin fecha objetivo'}</div></div><span class="badge ${done?'good':priorityClass(g.priority)}">${done?'Completado':priorityLabel(g.priority)}</span></div><div class="goalAmounts"><strong>${money(cur,g.currency||'PEN')}</strong><span>de ${money(target,g.currency||'PEN')}</span></div><div class="goalProgress"><i style="width:${p}%"></i></div><div class="goalStats"><div><span>Avance</span><strong>${pct(p)}</strong></div><div><span>Restante</span><strong>${money(remaining,g.currency||'PEN')}</strong></div><div><span>Ritmo sugerido</span><strong>${done?'—':months?`${money(monthly,g.currency||'PEN')}/mes`:money(remaining,g.currency||'PEN')}</strong></div></div>${g.note?`<div class="goalNote">${esc(g.note)}</div>`:''}<div class="entityActions">${!done?`<button class="btn small primary" onclick="openGoalContribution('${g.id}')"><i class="fa-solid fa-plus"></i> Aporte</button>`:''}<button class="btn small" onclick="openGoal('${g.id}')"><i class="fa-regular fa-pen-to-square"></i> Editar</button><button class="btn small danger" onclick="deleteGoal('${g.id}')"><i class="fa-regular fa-trash-can"></i> Eliminar</button></div></div>`}).join(''):'<div class="empty">No hay objetivos para este filtro.</div>'}
