function setAuthPanel(name){['authLoadingPanel','authLoginPanel','authPasswordPanel','authFatalPanel'].forEach(id=>$(id)?.classList.add('hidden'));$(name)?.classList.remove('hidden')}
function setAuthMessage(id,text='',type=''){const el=$(id);if(!el)return;el.textContent=text;el.className='authMessage'+(text?' show':'')+(type?' '+type:'')}
function setCloudStatus(state,label,detail=''){
  const dot=$('cloudDot'),txt=$('cloudStateLabel'),meta=$('cloudMeta');
  if(dot)dot.className='cloudDot '+state;if(txt)txt.textContent=label;if(meta&&detail)meta.textContent=detail;
}
function showApp(){document.body.classList.remove('authLocked');$('authGate')?.classList.add('hidden')}
function showLogin(message=''){document.body.classList.add('authLocked');$('authGate')?.classList.remove('hidden');setAuthPanel('authLoginPanel');if(cloudSession?.user?.email&&!$('authEmail').value)$('authEmail').value=cloudSession.user.email;if(message)setAuthMessage('authLoginMessage',message,'bad')}
function showPasswordSetup(){document.body.classList.add('authLocked');$('authGate')?.classList.remove('hidden');setAuthPanel('authPasswordPanel')}
function rawRemoteLooksEmpty(v){return !v||typeof v!=='object'||(!v.version&&!Array.isArray(v.accounts)&&!Array.isArray(v.cards)&&!Array.isArray(v.movements)&&!Array.isArray(v.recurring))}
function cloneState(v){try{return typeof structuredClone==='function'?structuredClone(v):JSON.parse(JSON.stringify(v))}catch{return JSON.parse(JSON.stringify(v))}}
function setCloudOnline(value){cloudOnline=!!value;applyAdminMode()}
function restoreCloudSnapshot(){
  if(!lastCloudSnapshot)return;
  cloudApplyingRemote=true;data=normalize(cloneState(lastCloudSnapshot));figuresHidden=!!data.settings.hideFigures;renderAll();updatePrivacyButton();cloudApplyingRemote=false;applyAdminMode();
}
function applyRemoteState(remoteData,updatedAt=''){
  const needsCategoryUpgrade=(+remoteData?.settings?.categoryModelVersion||0)<2;
  cloudApplyingRemote=true;
  data=normalize(cloneState(remoteData));figuresHidden=!!data.settings.hideFigures;cloudLastUpdated=updatedAt||'';lastCloudSnapshot=cloneState(data);
  const made=syncRecurring();renderAll();updatePrivacyButton();cloudApplyingRemote=false;applyAdminMode();
  return made||needsCategoryUpgrade;
}
function schedulePendingCloudSave(delay=90){
  if(!cloudReady||!cloudSession||!cloudOnline||cloudApplyingRemote)return;
  cloudSavePending=true;clearTimeout(cloudSaveTimer);setCloudStatus('busy','Guardando…','Guardando directamente en Supabase…');
  cloudSaveTimer=setTimeout(()=>{cloudSaveTimer=null;flushCloudSave()},delay);
}
function queueCloudSave(){schedulePendingCloudSave(90)}
async function flushCloudSave(){
  if(!cloudSavePending||!cloudReady||!cloudSession||!cloudOnline)return false;
  if(cloudBusy)return false;
  cloudSavePending=false;
  const ok=await cloudSaveState();
  if(cloudSavePending&&cloudOnline)schedulePendingCloudSave(60);
  return ok;
}
async function cloudSaveState(){
  if(!supabaseClient||!cloudSession||cloudBusy)return false;
  cloudBusy=true;setCloudStatus('busy','Guardando…','Guardando directamente en Supabase…');
  const snapshot=cloneState(data),expected=cloudLastUpdated;let conflict=false,ok=false;
  try{
    const stamp=new Date().toISOString();let row=null,error=null;
    if(expected){
      const result=await supabaseClient.from(CLOUD_TABLE).update({data:snapshot,updated_at:stamp}).eq('user_id',cloudSession.user.id).eq('updated_at',expected).select('updated_at').maybeSingle();
      row=result.data;error=result.error;if(error)throw error;if(!row){conflict=true;return false}
    }else{
      const result=await supabaseClient.from(CLOUD_TABLE).upsert({user_id:cloudSession.user.id,data:snapshot,updated_at:stamp},{onConflict:'user_id'}).select('updated_at').single();
      row=result.data;error=result.error;if(error)throw error;
    }
    cloudLastUpdated=row?.updated_at||stamp;lastCloudSnapshot=cloneState(snapshot);setCloudOnline(true);ok=true;
    setCloudStatus('good','Sincronizado',`Última sincronización: ${new Date(cloudLastUpdated).toLocaleString('es-PE')}. Datos financieros almacenados únicamente en Supabase.`);
    return true;
  }catch(err){
    console.error('Cloud save',err);cloudSavePending=false;setCloudOnline(false);restoreCloudSnapshot();
    setCloudStatus('bad','No guardado','No se pudo guardar en Supabase. El cambio fue descartado para mantener la nube como única fuente de verdad.');
    toast('Cambio descartado','No se pudo confirmar el cambio en Supabase. No se conservó una copia local.','bad');return false;
  }finally{
    cloudBusy=false;
    if(conflict){
      cloudSavePending=false;setCloudStatus('busy','Actualizando…','Se detectó un cambio más reciente en Supabase.');
      await cloudPullState(true);
      toast('Datos actualizados','Otro dispositivo tenía una versión más reciente. Se recargó Supabase para evitar sobrescribirla.','warn');
    }else if(ok&&cloudSavePending&&cloudOnline)schedulePendingCloudSave(60);
  }
}
async function cloudPullState(force=false){
  if(!supabaseClient||!cloudSession||cloudBusy)return false;
  if((cloudSaveTimer||cloudSavePending)&&!force)return false;
  if(force&&cloudSaveTimer){clearTimeout(cloudSaveTimer);cloudSaveTimer=null;await flushCloudSave()}
  if(cloudBusy)return false;
  cloudBusy=true;
  try{
    const {data:row,error}=await supabaseClient.from(CLOUD_TABLE).select('data,updated_at').eq('user_id',cloudSession.user.id).maybeSingle();
    if(error)throw error;
    if(!row||rawRemoteLooksEmpty(row.data)){setCloudOnline(false);setCloudStatus('bad','Sin datos en nube','No existe un estado válido en Supabase para esta cuenta.');return false}
    const remoteTime=row.updated_at||'';
    let needsSave=false;
    if(force||!cloudLastUpdated||remoteTime!==cloudLastUpdated)needsSave=applyRemoteState(row.data,remoteTime);
    setCloudOnline(true);
    setCloudStatus('good','Sincronizado',`Última sincronización: ${remoteTime?new Date(remoteTime).toLocaleString('es-PE'):'ahora'}. Datos financieros almacenados únicamente en Supabase.`);
    if(needsSave)cloudSavePending=true;
    return true;
  }catch(err){
    cloudApplyingRemote=false;console.error('Cloud pull',err);setCloudOnline(false);setCloudStatus('bad','Sin conexión','No se pudo consultar Supabase. Personal Hub queda en modo lectura y no conserva cambios locales.');return false;
  }finally{
    cloudBusy=false;if(cloudSavePending&&cloudOnline)schedulePendingCloudSave(60);
  }
}
async function bootstrapCloud(session){
  cloudSession=session;cloudReady=false;cloudOnline=false;cloudSavePending=false;clearTimeout(cloudSaveTimer);cloudSaveTimer=null;clearInterval(cloudPollTimer);
  if(!session?.user){showLogin();return}
  if($('cloudAccount'))$('cloudAccount').textContent=session.user.email||session.user.id;
  setCloudStatus('busy','Conectando…','Leyendo la información directamente desde Supabase…');
  try{
    const {data:row,error}=await supabaseClient.from(CLOUD_TABLE).select('data,updated_at').eq('user_id',session.user.id).maybeSingle();
    if(error)throw error;
    if(!row||rawRemoteLooksEmpty(row.data)){
      data=normalize(starter());figuresHidden=!!data.settings.hideFigures;cloudLastUpdated='';lastCloudSnapshot=null;cloudReady=true;cloudOnline=true;
      const made=syncRecurring();renderAll();updatePrivacyButton();applyAdminMode();
      const saved=await cloudSaveState();if(!saved)throw new Error('No se pudo crear el estado inicial en Supabase.');
      showApp();toast('Personal Hub Cloud activado','Supabase quedó configurado como única fuente de datos.');
    }else{
      cloudReady=true;cloudOnline=true;const needsSave=applyRemoteState(row.data,row.updated_at||'');showApp();
      setCloudStatus('good','Sincronizado',`Última sincronización: ${row.updated_at?new Date(row.updated_at).toLocaleString('es-PE'):'ahora'}. Datos financieros almacenados únicamente en Supabase.`);
      if(needsSave){cloudSavePending=true;await flushCloudSave()}
    }
    cloudPollTimer=setInterval(()=>{if(document.visibilityState==='visible')cloudPullState(false)},15000);
  }catch(err){
    cloudApplyingRemote=false;console.error('Cloud bootstrap',err);cloudReady=false;cloudOnline=false;setAuthPanel('authFatalPanel');$('authFatalText').textContent='No se pudo leer tu información de Supabase. Personal Hub no usará una copia local. Revisa tu conexión y vuelve a cargar la página.';
  }
}
async function initCloud(){
  if(!window.supabase?.createClient){setAuthPanel('authFatalPanel');$('authFatalText').textContent='No se pudo cargar el conector de Supabase. Revisa tu conexión a internet y vuelve a cargar.';return}
  /* Supabase may persist only the authentication session token so you do not need to log in on every reload. Financial data is never persisted by Personal Hub in browser storage. */
  supabaseClient=window.supabase.createClient(SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
  supabaseClient.auth.onAuthStateChange((event,session)=>{
    cloudSession=session||null;
    if(event==='SIGNED_OUT'){cloudReady=false;cloudOnline=false;cloudLastUpdated='';lastCloudSnapshot=null;data=normalize(starter());figuresHidden=false;showLogin();return}
    if(session&&(INVITE_LINK_TYPE==='invite'||INVITE_LINK_TYPE==='recovery'||event==='PASSWORD_RECOVERY')){showPasswordSetup();return}
    if(session&&!cloudReady)bootstrapCloud(session);
  });
  const {data:{session},error}=await supabaseClient.auth.getSession();
  if(error){showLogin(error.message);return}
  cloudSession=session;
  if(session&&(INVITE_LINK_TYPE==='invite'||INVITE_LINK_TYPE==='recovery'))showPasswordSetup();
  else if(session)bootstrapCloud(session);
  else showLogin();
}

