function updatePrivacyButton(){
  const b=$('privacyBtn');if(!b)return;
  b.classList.toggle('active',figuresHidden);
  b.setAttribute('aria-pressed',String(figuresHidden));
  b.setAttribute('aria-label',figuresHidden?'Mostrar cifras':'Ocultar cifras');
  b.title=figuresHidden?'Mostrar cifras':'Ocultar cifras';
  b.innerHTML=figuresHidden?'<i class="fa-solid fa-eye"></i><span>Mostrar</span>':'<i class="fa-solid fa-eye-slash"></i><span>Ocultar</span>';
}
function togglePrivacy(){
  if(!cloudReady||!cloudOnline)return toast('Solo nube','Conéctate a Supabase para guardar esta preferencia.','warn');
  figuresHidden=!figuresHidden;if(data?.settings)data.settings.hideFigures=figuresHidden;
  const d=$('detailDialog');if(d&&d.open)d.close();save();
  toast(figuresHidden?'Cifras ocultas':'Cifras visibles',figuresHidden?'La preferencia quedó guardada en Supabase.':'La preferencia quedó guardada en Supabase.');
}

